		return { requeued: !!r };
	}
	async function pageResult(ctx: TrustedContext, input: unknown) {
		await getOperation(ctx, input);
		const { operationId } = parse(operationRef, input);
		const o = await one<Operation>(
			db,
			sql`select * from medusa_operation where id=${operationId} and scope_kind=${ctx.scope.kind} and scope_id=${ctx.scope.id}`,
		);
		if (!o || !o.kind.startsWith("sync_")) throw new MedusaError("unsupported");
		return { processed: o.processed, nextCursor: o.next_cursor };
	}
	async function cancelOperation(ctx: TrustedContext, input: unknown) {
		await getOperation(ctx, input);
		const { operationId } = parse(operationRef, input);
		const cancelled = await one<Operation>(
			db,
			sql`update medusa_operation set status='cancelled',error_code='cancelled',updated_at=now() where id=${operationId} and scope_kind=${ctx.scope.kind} and scope_id=${ctx.scope.id} and status='queued' returning *`,
		);
		if (!cancelled) throw new MedusaError("conflict");
		return view(cancelled);
	}
	return {
		cancelOperation,
		getProduct: (ctx: TrustedContext, i: unknown) => get(ctx, "product", i),
		getOrder: (ctx: TrustedContext, i: unknown) => get(ctx, "order", i),
		listProducts: (ctx: TrustedContext, i: unknown) => list(ctx, "product", i),
		listOrders: (ctx: TrustedContext, i: unknown) => list(ctx, "order", i),
		getOperation,
		pageResult,
		requestResourceReconciliationInTransaction,
		requestSyncPageInTransaction,
		requestResourceReconciliation: (ctx: TrustedContext, i: unknown) =>
			db.transaction((tx) =>
				requestResourceReconciliationInTransaction(tx, ctx, i),
			),
		requestSyncPage: (ctx: TrustedContext, i: unknown) =>
			db.transaction((tx) => requestSyncPageInTransaction(tx, ctx, i)),
		receiptInTransaction,
		runOperation,
		runInbox,
		recover,
		retryReceiptInTransaction,
		connection,
	};
}

import { randomUUID } from "node:crypto";
import { readBoundedBody, signWebhook } from "../webhooks/protocol.server";
import {
	type BridgeEvent,
	bridgeEvent,
	connectionId,
	MedusaError,
	parse,
	safeError,
} from "./contract";
import { deadline, validateEndpoint } from "./transport.server";
export const BRIDGE_PROTOCOL = "application-bridge.standard-webhooks-v1";
/** Provider-project producer. Call with a retained ID to reuse it for an in-process delivery retry. */
export async function deliverBridge(
	event: Omit<BridgeEvent, "id" | "version"> & { id?: string },
	configuration: {
		targetUrl: string;
		connectionId: string;
		secret: string;
		signal?: AbortSignal;
		development?: boolean;
		fetch?: typeof fetch;
	},
) {
	parse(connectionId, configuration.connectionId);
	const u = new URL(configuration.targetUrl);
	const origin = validateEndpoint(
		configuration.targetUrl.match(/^https?:\/\/[^/]+/)?.[0] ?? "",
		configuration.development,
	);
	if (
		u.username ||
		u.password ||
		u.hash ||
		u.search ||
		u.pathname !==
			`/api/integrations/medusa/webhooks/${configuration.connectionId}` ||
		!configuration.secret.startsWith("whsec_")
	)
		throw new MedusaError("unconfigured");
	const data = parse(bridgeEvent, {
		...event,
		id: event.id ?? randomUUID(),
		version: 1,
	});
	const bytes = Buffer.from(JSON.stringify(data));
	if (bytes.length > 256 * 1024) throw new MedusaError("limit_exceeded");
	const d = deadline(configuration.signal);
	const timestamp = Math.floor(Date.now() / 1000);
	const signature = signWebhook(
		data.id,
		timestamp,
		bytes,
		configuration.secret,
	);
	try {
		const r = await (configuration.fetch ?? fetch)(origin + u.pathname, {
			method: "POST",
			redirect: "error",
			signal: d.signal,
			headers: {
				"content-type": "application/json",
				"webhook-id": data.id,
				"webhook-timestamp": String(timestamp),
				"webhook-signature": signature,
			},
			body: bytes,
		});
		await readBoundedBody(r.body, 2 * 1024 * 1024, d.signal);
		d.signal.throwIfAborted();
		if (!r.ok) throw new MedusaError("unavailable");
		return { id: data.id };
	} catch (e) {
		if (d.signal.aborted)
			throw new MedusaError(
				d.timeout.aborted ? "deadline_exceeded" : "cancelled",
			);
		throw safeError(e);
	}
}

